function update(key:string,v:any){setDraft(d=>d?{...d,[key]:key==='state'?String(v).toUpperCase():v,...(d.kind==='projects'&&!d.revision&&['audience','startDate'].includes(key)?(()=>{const p=key==='audience'?(settings.processes||[]).find((p:any)=>p.audience===v):d.processSnapshot;const stages=p?scheduledSteps(p.steps,key==='startDate'?v||today():d.startDate||today()):defaultStages();return {processSnapshot:p?structuredClone(p):null,stages,deadline:stages.at(-1)?.deadline||''};})():{}),...(key==='status'&&d.kind==='projects'?{workflowStatus:({Briefing:'Em alinhamento',Layout:'Em execução',Modelagem:'Em execução',Apresentação:'Em aprovação',Detalhamento:'Em execução','Pendente do cliente / profissional':'Pendente do cliente / profissional',Concluído:'Entregue'} as any)[v]}:{}),...(key==='client'&&v&&['budgets','projects'].includes(d.kind)?{audience:rows.find(r=>r.id===v)?.clientType||d.audience||'Cliente final',...(!d.revision&&d.kind==='budgets'?{processSnapshot:structuredClone((settings.processes||[]).find((p:any)=>p.audience===(rows.find(r=>r.id===v)?.clientType||d.audience||'Cliente final'))||null)}:{})}:{}),...(key==='room'?{questions:questions(v)}:{}),...(key==='project'&&v?{client:rows.find(r=>r.id===v)?.client||d.client||''}:{}),...(key==='client'&&d.project&&rows.find(r=>r.id===d.project)?.client!==v?{project:''}:{})}:d);}
async function prepareAttachment():Promise<Entry|null>{const entry=draftRef.current;if(!entry)return null;const error=validateRecord(entry);if(error){toast.error(error);return null;}if(!await persist(entry))return null;const saved=lastSavedRef.current;if(saved){draftRef.current=saved;setDraft(saved);originalRef.current=structuredClone(saved);}return saved;}
